source.sine_lfo:
@init
phase = 0;

@tick
dt = 1 / 30;
phase += rate_hz * dt;
cv = offset + amp * sin(phase * 6.2832);
output('cv', cv);

source.smooth:
@init
y = 0;

@tick
y += alpha * (input('in') - y);
output('cv', y);

source.threshold:
@init
state = 0;

@tick
v = input('in');
v > hi ? state = 1 : v < lo ? state = 0 : 0;
output('gate', state);

source.moving_avg:
@init
buf = 0; idx = 0; filled = 0; acc = 0;

@tick
v = input('in');
old = buf[idx];
buf[idx] = v;
acc += v - old;
idx += 1;
idx >= n ? idx = 0;
filled < n ? filled += 1;
output('cv', filled ? acc / filled : v);

source.mdct_flux:
@init
buf = 0; idx = 0; prev_e = 0;

@tick
buf[idx] = input('in');
idx += 1;
idx >= 64 ? (
  idx = 0;
  mdct(0, 64);
  e = 0; k = 0;
  loop(32, e += buf[k] * buf[k]; k += 1;);
  flux = abs(e - prev_e);
  prev_e = e;
);
output('flux', flux);

source.toggle:
@init
state = initial;

@tick
input('trig') > 0 ? state = 1 - state;
output('state', state);

source.accum:
@init
acc = 0; prev = 0;

@tick
v = input('in') > 0;
v > prev ? acc += per_tick : 0;
prev = v;
wrap > 0 && acc >= wrap ? acc = 0;
output('acc', acc);

source.hadamard4:
@init
s0 = 0; s1 = 0; s2 = 0;

@tick
v = input('in');
output('w', v + s0 + s1 + s2);
output('y', v - s0 + s1 - s2);
output('x', v + s0 - s1 - s2);
output('z', v - s0 - s1 + s2);
s2 = s1;
s1 = s0;
s0 = v;

source.gate_xor:
@tick
a = input('a') > 0.5; b = input('b') > 0.5;
output('q', a != b ? 1 : 0);

source.gate_xnor:
@tick
a = input('a') > 0.5; b = input('b') > 0.5;
output('q', a == b ? 1 : 0);

source.gate_imply:
@tick
a = input('a') > 0.5; b = input('b') > 0.5;
output('q', a && b || !a ? 1 : 0);

source.gate_nimply:
@tick
a = input('a') > 0.5; b = input('b') > 0.5;
output('q', a && !b ? 1 : 0);

source.alogic:
@init
st = 0;

@tick
v = input('in');
t = thresh;
family == 0 ? q = v > 0.6;                       // DL: diode drop
family == 1 ? (                                   // TDL: tunnel latch
  v > t + 0.1 ? st = 1 : v < t - 0.1 ? st = 0;
  q = st;
);
family == 2 ? (                                   // NL: neon strike
  v > 0.75 ? st = 1 : v < 0.4 ? st = 0;
  q = st;
);
family == 3 ? q = v > t;                          // MOS: sharp
family == 4 ? (                                   // CML: small swing
  d = v - t;
  d > 0.25 ? d = 0.25 : d < -0.25 ? d = -0.25;
  q = 0.5 + d;
);
family == 5 ? (                                   // QCA: majority cell
  a = v > t; b = cell_b > 0.5; c = cell_c > 0.5;
  q = a + b + c >= 2;
);
q = q ? 1 : 0;
output('q', q);

source.cnot:
@tick
c = input('c');
output('out', input('t') * (c > 0.5 ? -1 : 1));
output('c_out', c);

source.toffoli:
@tick
c = input('c1') > 0.5 && input('c2') > 0.5;
output('out', input('t') * (c ? -1 : 1));
output('c_out', input('c1'));
